package app.dayflow.almanac;import android.os.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import java.time.*;import com.nlf.calendar.*;
/** Optional offline traditional almanac; no host data or permissions. */
public final class MainActivity extends AppCompatActivity {private LinearLayout root;public void onCreate(Bundle state){getDelegate().setLocalNightMode(getIntent().getBooleanExtra("dayflow_dark",false)?androidx.appcompat.app.AppCompatDelegate.MODE_NIGHT_YES:androidx.appcompat.app.AppCompatDelegate.MODE_NIGHT_NO);super.onCreate(state);com.google.android.material.color.DynamicColors.applyToActivityIfAvailable(this,new com.google.android.material.color.DynamicColorsOptions.Builder().setContentBasedSource(getIntent().getIntExtra("dayflow_seed",0xff386a5c)).build());ScrollView scroll=new ScrollView(this);root=Ui.padded(this);scroll.setBackgroundColor(Ui.surface(this));scroll.addView(root);setContentView(scroll);androidx.core.view.ViewCompat.setOnApplyWindowInsetsListener(scroll,(v,insets)->{androidx.core.graphics.Insets bars=insets.getInsets(androidx.core.view.WindowInsetsCompat.Type.systemBars());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);return androidx.core.view.WindowInsetsCompat.CONSUMED;});LocalDate day=LocalDate.now();try{day=LocalDate.parse(getIntent().getStringExtra("dayflow_date"));}catch(Exception ignored){}show(day);}private void show(LocalDate day){root.removeAllViews();root.addView(Ui.text(this,day.toString(),26,true));try{Lunar lunar=Solar.fromYmd(day.getYear(),day.getMonthValue(),day.getDayOfMonth()).getLunar();root.addView(Ui.text(this,lunar.toFullString(),17,false));root.addView(Ui.text(this,"宜",20,true));root.addView(Ui.text(this,String.join(" · ",lunar.getDayYi()),17,false));root.addView(Ui.text(this,"忌",20,true));root.addView(Ui.text(this,String.join(" · ",lunar.getDayJi()),17,false));}catch(Exception e){root.addView(Ui.help(this,"该日期暂无黄历数据"));}LinearLayout row=Ui.row(this);row.addView(Ui.button(this,"前一天",false,()->show(day.minusDays(1))),new LinearLayout.LayoutParams(0,-2,1));row.addView(Ui.button(this,"后一天",false,()->show(day.plusDays(1))),new LinearLayout.LayoutParams(0,-2,1));root.addView(row);root.addView(Ui.help(this,"黄历仅作传统文化参考。插件完全离线，不获取日程、位置和账号。"));root.addView(Ui.button(this,"返回日栖",true,this::finish));}}
